import { ApiProperty } from "@nestjs/swagger";
import { STATUS_CODE } from "../response/status-code.enum";

export class WrappedResponseDto {
  @ApiProperty({
    description: "Indicates whether the request succeeded or failed.",
    example: true,
  })
  public success = true;

  @ApiProperty({
    description: "HTTP-equivalent status code reflecting the outcome.",
    enum: STATUS_CODE,
    example: STATUS_CODE.OK,
  })
  public statusCode: STATUS_CODE = STATUS_CODE.OK;

  @ApiProperty({
    description: "List of human-readable messages describing the result.",
    example: ["Operation completed successfully"],
  })
  public messages = ["Operation completed successfully"];

  @ApiProperty({
    description:
      "Response payload. Contains the result on success, or null on error or list of errors if applicable.",
    nullable: true,
    example: undefined,
  })
  public data = undefined;
}

import { IsInt, IsOptional, IsBoolean, IsNumber } from "class-validator";

export class ExponentialBackoffRetryDto {
  @IsOptional()
  @IsInt()
  @IsNumber()
  public retries?: number = 5; // Default value of 5 retries

  @IsOptional()
  @IsInt()
  @IsNumber()
  public baseDelayMs?: number = 1000; // Default value of 1000 ms

  @IsOptional()
  @IsBoolean()
  public jitter?: boolean = true; // Default value for jitter is true

  @IsOptional()
  @IsInt()
  @IsNumber()
  public attempt?: number = 1; // Default value of 1 attempt

  @IsOptional()
  @IsInt()
  @IsNumber()
  public maxBackoff?: number = 32; // Default value for max backoff is 32
}

import { randomInt } from "node:crypto";
import { ApiLogContext } from "../../../modules/logger";
import { ApiLoggerService } from "../../../modules/logger/apis/services/api-logger.service";
import { ExponentialBackoffRetryDto } from "./dtos/exponential-backoff-retry.dto";

/**
 * Calculates the delay for the next retry attempt using exponential backoff with a random jitter.
 * @param attempt - The current attempt number.
 * @param maxBackoff - The maximum backoff time in seconds.
 * @returns The calculated delay in milliseconds.
 */
export function calculateExponentialBackoffDelay(
  attempt: number,
  maxBackoff: number,
): number {
  const randomNumberMilliseconds = randomInt(0, 1000); // Random number between 0 and 1000
  const exponentialDelay = 2 ** attempt; // 2^n

  return Math.min(
    exponentialDelay * 1000 + randomNumberMilliseconds,
    maxBackoff * 1000,
  );
}

/**
 * Retries a given asynchronous operation a specified number of times with an exponential backoff delay between attempts.
 * @template T
 * @param logger - The logger instance used for logging retry information.
 * @param context - The logging context (service, method, etc.).
 * @param operation - The asynchronous operation to retry.
 * @param options - Configuration options for retries and delays.
 * @returns The result of the successful operation.
 */
export async function exponentialBackoffRetry<T>(
  logger: ApiLoggerService,
  context: ApiLogContext,
  operation: () => Promise<T>,
  options: ExponentialBackoffRetryDto,
): Promise<T> {
  const {
    retries = 5,
    baseDelayMs = 1000,
    jitter = true,
    attempt = 1,
    maxBackoff = 32,
  } = options;

  try {
    return await operation();
  } catch (error: unknown) {
    // ✅ Use a type guard instead of `any`
    const typedError = error as {
      code?: number;
      name?: string;
      message?: string;
    };

    const isRetryableError =
      typedError.code === 429 ||
      (typeof typedError.code === "number" &&
        typedError.code >= 500 &&
        typedError.code < 600) ||
      typedError.message?.includes("The client is closed") ||
      typedError.message?.includes("Socket closed unexpectedly") ||
      typedError.name === "AbortError" ||
      (typedError.name === "ReplyError" &&
        (typedError.message?.includes("TRYAGAIN") ||
          typedError.message?.includes("READONLY")));

    if (!isRetryableError) {
      logger.error(
        `Non-retryable error: ${typedError.message ?? "Unknown error"}`,
        context,
      );
      throw error;
    }

    if (attempt >= retries) {
      logger.error(
        `Operation failed after ${retries} retries: ${typedError.message ?? "Unknown error"}`,
        context,
      );
      throw error;
    }

    const delay = jitter
      ? calculateExponentialBackoffDelay(attempt, maxBackoff)
      : baseDelayMs * 2 ** (attempt - 1);

    logger.warn(`Retry attempt ${attempt}/${retries} in ${delay}ms`, context);

    await new Promise<void>((resolve) => {
      setTimeout(resolve, delay);
    });

    return exponentialBackoffRetry(logger, context, operation, {
      ...options,
      attempt: attempt + 1,
    });
  }
}

import {
  HttpException,
  HttpStatus,
  ValidationError,
  ValidationPipe,
} from "@nestjs/common";
import { ResponseWrapper } from "../response/response-wrapper";
import { STATUS_CODE } from "../response/status-code.enum";

/**
 * @param errors - Nested validation errors from class-validator.
 * @returns Flat list of all constraint message strings.
 */
function collectMessages(errors: Array<ValidationError>): Array<string> {
  return errors.flatMap((error) => [
    ...Object.values(error.constraints ?? {}),
    ...collectMessages(error.children ?? []),
  ]);
}

export class WrapperValidationPipe extends ValidationPipe {
  public constructor() {
    super({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      exceptionFactory: (errors: Array<ValidationError>): HttpException => {
        return new HttpException(
          ResponseWrapper.error(
            STATUS_CODE.BAD_REQUEST,
            collectMessages(errors),
          ),
          HttpStatus.OK,
        );
      },
    });
  }
}

