import { Controller, Post, Req, Res, Logger } from "@nestjs/common";
import { Request, Response } from "express";
import { DatadogProxyService } from "./datadog-proxy.service";

@Controller("datadog-proxy")
export class DatadogProxyController {
  private readonly logger = new Logger(DatadogProxyController.name);

  public constructor(
    private readonly datadogProxyService: DatadogProxyService,
  ) {}

  @Post()
  public async forward(
    @Req() request: Request,
    @Res() response: Response,
  ): Promise<void> {
    try {
      const result = await this.datadogProxyService.forwardToDatadog(request);
      response.status(result.status).send(result.data);
    } catch (error) {
      this.logger.error("Datadog proxy forwarding failed", error);
      response.status(502).json({ message: "Failed to forward to Datadog" });
    }
  }
}

import {
  DynamicModule,
  Global,
  InjectionToken,
  Module,
  Provider,
  Type,
} from "@nestjs/common";
import { DatadogProxyController } from "./datadog-proxy.controller";
import { DatadogProxyService } from "./datadog-proxy.service";
import {
  DATADOG_PROXY_CONFIG,
  IDatadogProxyConfig,
} from "./interfaces/datadog-proxy-config.interface";

export interface DatadogProxyModuleAsyncOptions {
  imports?: Array<Type | DynamicModule>;
  useFactory: (
    ...arguments_: Array<unknown>
  ) => IDatadogProxyConfig | Promise<IDatadogProxyConfig>;
  inject?: Array<InjectionToken>;
}

@Global()
@Module({})
export class DatadogProxyModule {
  public static forRootAsync(
    options: DatadogProxyModuleAsyncOptions,
  ): DynamicModule {
    const configProvider: Provider = {
      provide: DATADOG_PROXY_CONFIG,
      useFactory: options.useFactory,
      inject: options.inject || [],
    };

    return {
      controllers: [DatadogProxyController],
      exports: [DatadogProxyService],
      imports: options.imports || [],
      module: DatadogProxyModule,
      providers: [configProvider, DatadogProxyService],
    };
  }
}

import { Inject, Injectable, Logger } from "@nestjs/common";
import axios, { AxiosResponse } from "axios";
import { Request } from "express";
import { ForwardHeadersDto } from "./dtos/forward-headers.dto";
import {
  DATADOG_PROXY_CONFIG,
  IDatadogProxyConfig,
} from "./interfaces/datadog-proxy-config.interface";

@Injectable()
export class DatadogProxyService {
  private readonly logger = new Logger(DatadogProxyService.name);

  public constructor(
    @Inject(DATADOG_PROXY_CONFIG)
    private readonly config: IDatadogProxyConfig,
  ) {}

  public async forwardToDatadog(
    request: Request,
  ): Promise<{ status: number; data: unknown }> {
    const { ddforward } = request.query as {
      [key: string]: string | undefined;
    };
    if (!ddforward || typeof ddforward !== "string") {
      this.logger.warn("Missing ddforward parameter");
      return { status: 400, data: { message: "Missing ddforward parameter" } };
    }

    let targetUrl: URL;
    try {
      // Ddforward may be an absolute URL or a relative path from the SDK
      targetUrl =
        ddforward.startsWith("http://") || ddforward.startsWith("https://")
          ? new URL(ddforward)
          : new URL(ddforward, this.config.intakeUrl);
    } catch {
      this.logger.warn(`Invalid ddforward URL: ${ddforward}`);
      return { status: 400, data: { message: "Invalid ddforward URL" } };
    }

    // Replace/inject real Datadog credentials in query parameters
    targetUrl.searchParams.set("dd-api-key", this.config.clientToken);
    targetUrl.searchParams.set("dd-application-id", this.config.applicationId);

    const { body } = request;

    // The RUM SDK sends the body as a Buffer (newline-delimited JSON).
    // Each line may contain "application":{"id":"..."} with the fake frontend
    // Credentials. Replace them with the real ones so Datadog can match the session.
    let forwardBody: Buffer | string = body;
    if (Buffer.isBuffer(body)) {
      try {
        const text = body.toString("utf8");
        const corrected = text
          .split("\n")
          .map((line) => {
            if (!line.trim()) return line;
            try {
              const object = JSON.parse(line);
              if (object.application?.id) {
                object.application.id = this.config.applicationId;
              }
              return JSON.stringify(object);
            } catch {
              return line;
            }
          })
          .join("\n");
        forwardBody = corrected;
      } catch {
        // If parsing fails, forward the original body as-is
        this.logger.warn(
          "Failed to rewrite application.id in body, forwarding as-is",
        );
      }
    }

    const finalUrl = targetUrl.toString();
    const response: AxiosResponse = await axios.post(finalUrl, forwardBody, {
      headers: new ForwardHeadersDto(
        (request.headers["content-type"] as string) || "application/json",
      ).toRecord(),
      validateStatus: () => true,
    });
    return { status: response.status, data: response.data };
  }
}

export class ForwardHeadersDto {
  public contentType: string;

  public constructor(contentType?: string) {
    this.contentType = contentType ?? "application/json";
  }

  /**
   * Return a headers record suitable for axios without using literal dash-named
   * object properties (avoids ESLint naming-convention complaints).
   * @returns headerName the header
   */
  public toRecord(): Record<string, string> {
    const headerName = "Content-Type";
    return { [headerName]: this.contentType };
  }
}

