import { Logger } from "@nestjs/common";
import { LogEntryDto } from "../../../../common/dtos/log-entry.dto";
import { ApiLogContext } from "../dtos/api-log-context.dto";

export class ApiLoggerService {
  private static formatMessage(
    message: string,
    context: ApiLogContext,
    error?: Error,
  ): string {
    const { service, method, caller, plant } = context;

    if (!service || !method || !caller || !plant) {
      throw new Error("Missing mandatory fields in API log context");
    }

    const logEntry: LogEntryDto = {
      context,
      message,
      timestamp: new Date().toISOString(),
      ...(error && { error: error.message, stack: error.stack }),
    };

    return JSON.stringify(logEntry);
  }

  private readonly logger = new Logger(ApiLoggerService.name);

  public log(message: string, context: ApiLogContext): void {
    this.logger.log(ApiLoggerService.formatMessage(message, context));
  }

  public error(message: string, context: ApiLogContext, error?: Error): void {
    this.logger.error(ApiLoggerService.formatMessage(message, context, error));
  }

  public warn(message: string, context: ApiLogContext): void {
    this.logger.warn(ApiLoggerService.formatMessage(message, context));
  }

  public debug(message: string, context: ApiLogContext): void {
    this.logger.debug(ApiLoggerService.formatMessage(message, context));
  }

  public verbose(message: string, context: ApiLogContext): void {
    this.logger.verbose(ApiLoggerService.formatMessage(message, context));
  }

  public fatal(message: string, context: ApiLogContext, error?: Error): void {
    this.logger.fatal(ApiLoggerService.formatMessage(message, context, error));
  }
}

