import { describe, it, beforeEach, expect } from "@jest/globals";
import { JobsLoggerService } from "./jobs-logger.service";

describe("JobsLoggerServiceTest", () => {
  let jobsLoggerService: JobsLoggerService;

  beforeEach(async () => {});
  describe("Jobs logger service", () => {
    it('should log only error and warn when minimum level is warn"', () => {
      const originalWrite = process.stdout.write;
      let stdoutOutput = "";
      process.stdout.write = (chunk:any) => {
        stdoutOutput += chunk;
        let arg: any = arguments;
        originalWrite.apply(process.stdout, arg);
      };

      const originalErrWrite = process.stdout.write;
      let stdErrOutput = "";
      process.stderr.write = function (chunk:any):any {
        stdErrOutput += chunk;
      };

      jobsLoggerService = new JobsLoggerService("warn");

      jobsLoggerService.error("error message", {
        method: "method",
        service: "service",
      });
      jobsLoggerService.warn("warn message", {
        method: "method",
        service: "service",
      });
      jobsLoggerService.log("log message", {
        method: "method",
        service: "service",
      });

      process.stderr.write = originalErrWrite;
      expect(stdErrOutput).toContain("error message");
      expect(stdoutOutput).toContain("warn message");
      expect(stdoutOutput).not.toContain("log message");
    });
  });
});

import { Logger, LogLevel } from "@nestjs/common";
import { LogEntryDto } from "../../../../common/dtos/log-entry.dto";
import { JobsLogContext } from "../dtos/jobs-log-context.dto";

export class JobsLoggerService {
  //= new Logger({context:JobsLoggerService.name,logLevels:["verbose","debug","log","warn","error","fatal"]});
  private static readonly logLevels: Array<LogLevel> = [
    "verbose",
    "debug",
    "log",
    "warn",
    "error",
    "fatal",
  ];

  private static formatMessage(
    message: string,
    context: JobsLogContext,
    error?: Error,
  ): string {
    const { service, method } = context;

    if (!service || !method) {
      throw new Error("Missing mandatory fields in Jobs log context");
    }

    const logEntry: LogEntryDto = {
      context: { ...context, userId: "MESXSystem" },
      message,
      timestamp: new Date().toISOString(),
      ...(error && { error: error.message, stack: error.stack }),
    };

    return JSON.stringify(logEntry);
  }

  // Injected from main app
  private static getLogLevels(minLogLevel: LogLevel): Array<LogLevel> {
    const minLevelIndex = JobsLoggerService.logLevels.indexOf(minLogLevel);
    if (minLevelIndex === -1) {
      throw new Error(`Invalid log level: ${minLogLevel}`);
    }
    return this.logLevels.slice(minLevelIndex);
  }

  private readonly logger;

  public constructor(minLogLevel: LogLevel) {
    this.logger = new Logger(JobsLoggerService.name);

    this.logger.localInstance?.setLogLevels?.(
      JobsLoggerService.getLogLevels(minLogLevel ?? "log"),
    );
  }

  public log(message: string, context: JobsLogContext): void {
    this.logger.log(JobsLoggerService.formatMessage(message, context));
  }

  public error(message: string, context: JobsLogContext, error?: Error): void {
    this.logger.error(JobsLoggerService.formatMessage(message, context, error));
  }

  public warn(message: string, context: JobsLogContext): void {
    this.logger.warn(JobsLoggerService.formatMessage(message, context));
  }

  public debug(message: string, context: JobsLogContext): void {
    this.logger.debug(JobsLoggerService.formatMessage(message, context));
  }

  public verbose(message: string, context: JobsLogContext): void {
    this.logger.verbose(JobsLoggerService.formatMessage(message, context));
  }

  public fatal(message: string, context: JobsLogContext, error?: Error): void {
    this.logger.fatal(JobsLoggerService.formatMessage(message, context, error));
  }

  public updateMinLogLevel(minLogLevel: LogLevel): void {
    this.logger.localInstance?.setLogLevels?.(
      JobsLoggerService.getLogLevels(minLogLevel ?? "log"),
    );
  }
}

