/**
 * OpenTelemetry tracing initialization for Datadog RUM–Traces correlation.
 *
 * IMPORTANT: This file MUST be imported at the very top of main.ts,
 * before any NestJS or Express imports, so that HTTP patching takes effect.
 *
 * The W3CTraceContextPropagator reads the `traceparent` / `tracestate` headers
 * injected by the Datadog Browser RUM SDK and propagates the trace context
 * through every outgoing HTTP call, allowing end-to-end correlation between
 * browser sessions and backend spans in the Datadog APM UI.
 *
 */

import { Logger } from "@nestjs/common";
import { W3CTraceContextPropagator } from "@opentelemetry/core";
import { OTLPTraceExporter as OTLPTraceExporterGrpc } from "@opentelemetry/exporter-trace-otlp-grpc";
import { OTLPTraceExporter } from "@opentelemetry/exporter-trace-otlp-http";
import { OTLPTraceExporter as OTLPTraceExporterProto } from "@opentelemetry/exporter-trace-otlp-proto";
import "dotenv/config";
import { HttpInstrumentation } from "@opentelemetry/instrumentation-http";
import { resourceFromAttributes } from "@opentelemetry/resources";
import { NodeSDK } from "@opentelemetry/sdk-node";
import { TracingResourceAttributesDto } from "./dto/tracing-resource-attributes.dto";

const logger = new Logger("Tracing");

const tracingEnvironmentVariableNames = [
  "OTEL_TRACING_ENABLED",
  "OTEL_ENV",
  "OTEL_SERVICE",
  "OTEL_EXPORTER_OTLP_PROTOCOL",
  "OTEL_EXPORTER_OTLP_ENDPOINT",
] as const;

const hasAnyTracingEnvironmentVariable = tracingEnvironmentVariableNames.some(
  (name) => {
    const value = process.env[name];
    return typeof value === "string" && value.trim().length > 0;
  },
);

const initializeTracing = (): void => {
  if (!hasAnyTracingEnvironmentVariable) {
    logger.warn(
      "No tracing environment variables were found. Skipping tracing initialization.",
    );
    return;
  }

  const isEnabled = process.env.OTEL_TRACING_ENABLED === "true";
  if (!isEnabled) {
    logger.log(
      'Tracing is disabled (OTEL_TRACING_ENABLED !== "true"). Skipping initialization.',
    );
    return;
  }

  try {
    /**
     * OTEL_EXPORTER_OTLP_PROTOCOL selects the transport to the collector:
     *   grpc         → port 4317  (OTLPTraceExporter from exporter-trace-otlp-grpc)
     *   http/protobuf → port 4318  (OTLPTraceExporter from exporter-trace-otlp-proto)
     *   http/json    → port 4318  (OTLPTraceExporter from exporter-trace-otlp-http)  ← default
     * OTEL_EXPORTER_OTLP_ENDPOINT overrides the address when the default doesn't fit.
     */
    const protocol = process.env.OTEL_EXPORTER_OTLP_PROTOCOL ?? "http/json";

    const defaultEndpoint =
      protocol === "grpc"
        ? "http://localhost:4317"
        : "http://localhost:4318/v1/traces";

    const exporterEndpoint =
      process.env.OTEL_EXPORTER_OTLP_ENDPOINT ?? defaultEndpoint;

    type SpanExporter =
      | OTLPTraceExporter
      | OTLPTraceExporterGrpc
      | OTLPTraceExporterProto;

    let exporter: SpanExporter;
    if (protocol === "grpc") {
      exporter = new OTLPTraceExporterGrpc({ url: exporterEndpoint });
    } else if (protocol === "http/protobuf") {
      exporter = new OTLPTraceExporterProto({ url: exporterEndpoint });
    } else {
      exporter = new OTLPTraceExporter({ url: exporterEndpoint });
    }

    const sdk = new NodeSDK({
      // Auto-instrument HTTP — this propagates traceparent/tracestate on
      // Outbound calls and reads them from inbound requests so every request
      // From the RUM SDK is linked to its backend span.
      instrumentations: [
        new HttpInstrumentation({
          ignoreIncomingRequestHook: (request): boolean => {
            // Skip OPTIONS (CORS preflight) and internal health routes
            if (request.method === "OPTIONS") return true;
            const url = request.url ?? "";
            return ["/probes", "/dapr/subscribe", "/health"].some((pattern) =>
              url.includes(pattern),
            );
          },
        }),
      ],

      resource: resourceFromAttributes(
        new TracingResourceAttributesDto(
          process.env.OTEL_ENV ?? "development",
          process.env.OTEL_SERVICE ?? "mesx",
          process.env.npm_package_version ?? "0.0.0",
        ).toAttributes(),
      ),

      // W3C Trace Context propagator: reads `traceparent` / `tracestate` headers
      // Injected by the Datadog RUM Browser SDK (propagatorTypes: ["tracecontext"]).
      textMapPropagator: new W3CTraceContextPropagator(),

      // Export traces via OTLP HTTP (NodeSDK wraps this in a BatchSpanProcessor)
      traceExporter: exporter,
    });

    sdk.start();
    logger.log(
      `Tracing started — protocol: ${protocol}, endpoint: ${exporterEndpoint}`,
    );

    // Graceful shutdown: flush batched spans before the process exits
    process.on("SIGTERM", () => {
      sdk
        .shutdown()
        .then(() => logger.log("Tracing shut down."))
        .catch((error: unknown) => logger.error("Shutdown error:", error));
    });
  } catch (error: unknown) {
    logger.error("Tracing initialization failed:", error);
  }
};

initializeTracing();

/**
 * Determines whether the given Redis error requires reauthentication.
 *
 * Checks the error message against a list of known critical Redis connection/authentication errors.
 * @param error - The error thrown by the Redis client.
 * @returns True if the error suggests that reauthentication should be attempted; otherwise, false.
 */
export function shouldReauthenticate(error: Error): boolean {
  const criticalErrors = [
    "WRONGPASS",
    "NOAUTH",
    "invalid username-password",
    "user is disabled",
    "Socket closed unexpectedly",
    "ECONNRESET",
    "Connection lost",
    "Redis connection lost",
  ];

  return criticalErrors.some((message) => error.message.includes(message));
}

import { Module, Global } from "@nestjs/common";
import { AzureManagedRedisConnection } from "./redis/connections/azure-managed-redis-redis-connection";
import { BasicAuthRedisConnection } from "./redis/connections/basic-auth-redis-connection";

@Global()
@Module({
  providers: [AzureManagedRedisConnection, BasicAuthRedisConnection],
  exports: [AzureManagedRedisConnection, BasicAuthRedisConnection],
})
export class RedisModule {}

import { createPool, Pool } from "generic-pool";
import {
  ApiLogContext,
  ApiLoggerService,
  JobsLoggerService,
} from "../../../logger";
import {
  RedisClientInstance,
  CompatibleRedisClientOptions,
} from "../types/redis-types";

export abstract class RedisConnectionService {
  protected redisClient?: RedisClientInstance;

  protected redisPool?: Pool<RedisClientInstance>;

  protected redisClientOptions?: CompatibleRedisClientOptions;

  protected tokenExpiryTimeout?: ReturnType<typeof setTimeout>;

  protected heartbeatTimer?: ReturnType<typeof setInterval>;

  private connectingClient?: Promise<RedisClientInstance>;

  public constructor(
    public readonly redisUrl: string,
    protected readonly usePool?: boolean,
    protected readonly poolMin?: number,
    protected readonly poolMax?: number,
    protected readonly customLogger?: ApiLoggerService | JobsLoggerService,
  ) {}

  public abstract createClient(): Promise<RedisClientInstance>;

  /**
   * Connect to Redis, either using a connection pool or a single client.
   * - If pooling is enabled, creates a pool and returns a pooled client.
   * - If pooling is disabled, returns a single Redis client instance.
   * @returns A connected Redis client instance (from pool or single client).
   */
  public async connect(): Promise<RedisClientInstance> {
    const context: ApiLogContext = {
      method: "createConnection",
      service: "RedisConnectionService",
      caller: "RedisConnectionService",
      plant: 0,
    };
    if (this.usePool) {
      const min = this.poolMin ?? 2;
      const max = this.poolMax ?? 4;

      // Initialize pool if it doesn't exist
      if (!this.redisPool) {
        this.redisPool = createPool<RedisClientInstance>(
          {
            create: async () => {
              const client = await this.createClient();
              client.on("error", (error) => {
                this.customLogger?.log("Redis Pool Client Error:", error);
                if (this.redisPool) this.redisPool.destroy(client);
              });
              return client;
            },
            destroy: async (client) => {
              await client.quit();
            },
            validate: (client) => Promise.resolve(client.isOpen),
          },
          { min, max, acquireTimeoutMillis: 5000, testOnBorrow: true },
        );

        // Warm up pool safely
        const pool = this.redisPool;
        const warmupClients = Array.from({ length: min }).map(async () => {
          const client = await pool.acquire();
          await pool.release(client);
        });
        await Promise.all(warmupClients);
        this.customLogger?.log(
          `Redis pool initialized: size=${this.redisPool.size}, available=${this.redisPool.available}`,
          context,
        );
      }

      // Acquire a client from the pool
      return this.redisPool.acquire();
    }

    // Single client connection
    if (!this.redisClient || !this.redisClient.isOpen) {
      this.redisClient = await this.createClient();
      this.redisClient.on("error", (error) => {
        console.error("Redis Client Error:", error);
        this.redisClient = undefined;
      });
    }

    return this.redisClient;
  }

  /** Gracefully disconnect from Redis */
  public async disconnect(): Promise<void> {
    if (this.usePool && this.redisPool) {
      await this.redisPool.drain();
      await this.redisPool.clear();
      this.redisPool = undefined;
    } else if (this.redisClient) {
      await this.redisClient.quit();
      this.redisClient.removeAllListeners();
      this.redisClient = undefined;
    }
  }

  /**
   * Get a Redis client from the pool or a single connection.
   * - If pooling is enabled, acquires a client from the pool.
   * - If pooling is disabled, returns the single client instance.
   * - Automatically reconnects if the client is missing.
   * @returns A connected Redis client instance (pooled or single).
   */
  public async getClient(): Promise<RedisClientInstance> {
    const context: ApiLogContext = {
      method: "getClient",
      service: "RedisConnectionService",
      caller: "RedisConnectionService",
      plant: 0,
    };
    // === POOL MODE ===
    if (this.usePool && this.redisPool) {
      let client = await this.redisPool.acquire();

      // Validate client before returning
      if (!client.isOpen) {
        this.customLogger?.log(
          "Redis pooled client is closed, destroying and creating a new one",
          context,
        );
        await this.redisPool.destroy(client);
        client = await this.redisPool.acquire();
      }

      return client;
    }

    // === SINGLE CLIENT MODE ===
    if (this.redisClient?.isOpen) {
      return this.redisClient;
    }

    // Avoid race condition: multiple calls creating multiple clients
    if (!this.connectingClient) {
      this.connectingClient = this.connect().finally(() => {
        this.connectingClient = undefined;
      });
    }

    this.redisClient = await this.connectingClient;

    if (!this.redisClient.isOpen) {
      throw new Error("Failed to obtain a connected Redis client");
    }

    return this.redisClient;
  }

  /**
   * Release a Redis client back to the pool.
   * Only applicable if pooling is enabled.
   * @param client - The Redis client instance to release
   */
  public async releaseClient(client: RedisClientInstance): Promise<void> {
    if (this.usePool && this.redisPool) await this.redisPool.release(client);
  }
}

import { DefaultAzureCredential } from "@azure/identity";
import { createClient } from "@redis/client";
import {
  EntraIdCredentialsProviderFactory,
  REDIS_SCOPE_DEFAULT,
} from "@redis/entraid";

import { ApiLogContext } from "../../../logger";
import { JobsLoggerService } from "../../../logger/jobs/services/jobs-logger.service";
import { RedisClientInstance } from "../types/redis-types";
import { RedisConnectionService } from "./abstract-redis-connection";

export class AzureManagedRedisConnection extends RedisConnectionService {
  public static createLogContext(
    method: string,
    caller = "",
    object?: string,
    plant = 0,
    userId?: string,
  ): ApiLogContext {
    return {
      caller,
      method,
      object,
      plant,
      service: AzureManagedRedisConnection.name,
      userId,
    };
  }

  /**
   * Safely extract a string error code from unknown errors
   * @param error error object to inspect
   * @returns string error code when present, otherwise undefined
   */
  private static getErrorCode(error: unknown): string | undefined {
    if (typeof error === "object" && error) {
      const candidate = (error as { code?: unknown }).code;
      if (typeof candidate === "string") return candidate;
    }
    return undefined;
  }

  private readonly credential = new DefaultAzureCredential();

  private readonly logger: JobsLoggerService;

  private lastReconnectTicks = 0;

  private firstErrorTime = 0;

  private previousErrorCount = 0;

  // Minimum time between reconnection attempts (in milliseconds)
  private readonly reconnectMinInterval = 60_000; // 60 seconds

  // Number of errors within the interval before forcing reconnect
  private readonly reconnectErrorThreshold = 3;

  // Connection and socket error codes that warrant a forced reconnect
  private readonly reconnectErrors = [
    "ECONNRESET", // Connection reset by peer
    "ECONNREFUSED", // Connection refused
    "ETIMEDOUT", // Operation timed out
    "ENOTFOUND", // DNS lookup failed
    "ENETUNREACH", // Network unreachable
    "EHOSTUNREACH", // Host unreachable
    "EPIPE", // Broken pipe
  ];

  // Tracks in-flight reconnection to avoid parallel reconnect attempts
  private reconnectInFlight?: Promise<RedisClientInstance>;

  public constructor(
    redisUrl: string,
    logger: JobsLoggerService,
    usePool?: boolean,
    poolMin?: number,
    poolMax?: number,
  ) {
    super(redisUrl, usePool, poolMin, poolMax);
    this.logger = logger;
  }

  /**
   * Creates a single Redis client using an azure managed redis.
   * This method is used when not using a connection pool, or
   * when a direct client instance is required.
   * @returns A connected Redis client instance.
   */ public async createClient(): Promise<RedisClientInstance> {
    const context =
      AzureManagedRedisConnection.createLogContext("createClient");

    const provider =
      EntraIdCredentialsProviderFactory.createForDefaultAzureCredential({
        credential: this.credential,
        onReAuthenticationError: (error) => {
          const errorMessage = JSON.stringify({ message: error.message });
          this.logger.error(
            `Re-authentication failed: ${errorMessage}`,
            context,
          );
        },
        onRetryableError: (errorMessage: string) => {
          const formattedMessage = JSON.stringify({ message: errorMessage });
          this.logger.error(
            `Retryable error during token refresh: ${formattedMessage}`,
            context,
          );
        },
        scopes: [REDIS_SCOPE_DEFAULT],
        tokenManagerConfig: {
          expirationRefreshRatio: 0.8,
          retry: {
            backoffMultiplier: 2,
            initialDelayMs: 500,
            isRetryable: (error) => {
              if (error instanceof Error) {
                const message = error.message.toLowerCase();
                return (
                  message.includes("network") ||
                  message.includes("timeout") ||
                  message.includes("rate limit")
                );
              }
              return false;
            },
            jitterPercentage: 0.2,
            maxAttempts: 5,
            maxDelayMs: 5000,
          },
        },
      });

    // Explicitly typed to match RedisClientInstance
    const client: RedisClientInstance = createClient({
      url: this.redisUrl,
      credentialsProvider: provider,
      socket: {
        tls: true,
        reconnectStrategy: (retries) => {
          if (retries > 10) return false;
          return Math.min(100 * 2 ** retries, 2000);
        },
      },
    });

    client.on("error", (error) => {
      this.logger.error("Redis client error", context, error);

      // In pool mode, let the pool destroy/replace the client.
      if (this.usePool) return;

      // Throttle reconnection attempts by reusing the same in-flight promise.
      this.reconnectInFlight ??= this.forceReconnectAsync(client, error)
        .then((newClient) => {
          this.redisClient = newClient;
          return newClient;
        })
        .finally(() => {
          this.reconnectInFlight = undefined;
        });
    });

    await client.connect();
    this.logger.log("Redis connected with Azure Managed Redis", context);

    return client;
  }

  /**
   * Force reconnection to Redis similar to StackExchange.Redis ForceReconnect pattern.
   * This should be called when encountering connection errors like ECONNRESET, ETIMEDOUT, etc.
   * Implements throttling to prevent cascade failures during server overload.
   * @param client - The current Redis client to reconnect
   * @param error - The error that triggered the reconnection
   * @returns A new connected Redis client instance or the existing one if throttled
   */
  private async forceReconnectAsync(
    client: RedisClientInstance,
    error: Error,
  ): Promise<RedisClientInstance> {
    const context = AzureManagedRedisConnection.createLogContext(
      "forceReconnectAsync",
    );
    const currentTicks = Date.now();

    const errorCode = AzureManagedRedisConnection.getErrorCode(error);
    const shouldForceReconnect = this.shouldForceReconnect(errorCode);

    if (!shouldForceReconnect) {
      this.logger.warn(
        `Error ${errorCode} does not require force reconnection`,
        context,
      );
      return client;
    }

    // Check if enough time has passed since last reconnect
    const timeSinceLastReconnect = currentTicks - this.lastReconnectTicks;
    if (timeSinceLastReconnect < this.reconnectMinInterval) {
      this.logger.warn(
        `Throttling reconnection. Time since last reconnect: ${timeSinceLastReconnect}ms (min: ${this.reconnectMinInterval}ms)`,
        context,
      );
      return client;
    }

    // Track errors within the interval
    if (this.firstErrorTime === 0) {
      this.firstErrorTime = currentTicks;
      this.previousErrorCount = 1;
    } else {
      const errorInterval = currentTicks - this.firstErrorTime;
      if (errorInterval < this.reconnectMinInterval) {
        this.previousErrorCount += 1;
      } else {
        // Reset counter if we're outside the interval
        this.firstErrorTime = currentTicks;
        this.previousErrorCount = 1;
      }
    }

    // Only force reconnect if we've exceeded the error threshold
    if (this.previousErrorCount < this.reconnectErrorThreshold) {
      this.logger.warn(
        `Error count ${this.previousErrorCount} below threshold ${this.reconnectErrorThreshold}. Not forcing reconnection yet.`,
        context,
      );
      return client;
    }

    this.logger.warn(
      `Forcing reconnection due to ${errorCode ?? "unknown"} error. Error count: ${this.previousErrorCount}`,
      context,
    );

    try {
      // Disconnect the old client gracefully
      if (client.isOpen) {
        await client.quit().catch((quitError) => {
          this.logger.warn(
            `Error during graceful quit: ${quitError.message}`,
            context,
          );
        });
      }
    } catch (disposeError) {
      this.logger.warn(
        `Error disposing old client: ${(disposeError as Error).message}`,
        context,
      );
    }

    // Create a new client
    const newClient = await this.createClient();

    // Update reconnect tracking
    this.lastReconnectTicks = Date.now();
    this.previousErrorCount = 0;
    this.firstErrorTime = 0;

    this.logger.log("Successfully forced reconnection to Redis", context);
    return newClient;
  }

  /**
   * Determines if an error should trigger a forced reconnection
   * @param errorCode Redis error code used to decide if reconnection is required
   * @returns true when the error code warrants a force reconnect
   */
  private shouldForceReconnect(errorCode?: string): boolean {
    // Force reconnect for connection errors and socket errors
    if (!errorCode) return false;
    return this.reconnectErrors.includes(errorCode);
  }

  /**
   * Wraps Redis operations with automatic reconnection on errors.
   * Use this method for executing Redis commands with built-in error handling.
   * @param client Redis client instance to execute the operation against
   * @param operation Async operation that receives the Redis client
   * @returns Result of the operation and the active client (possibly a new one after reconnect)
   */
  public async executeWithReconnect<T>(
    client: RedisClientInstance,
    operation: (client: RedisClientInstance) => Promise<T>,
  ): Promise<{ result: T; client: RedisClientInstance }> {
    const context = AzureManagedRedisConnection.createLogContext(
      "executeWithReconnect",
    );

    try {
      const result = await operation(client);
      return { result, client };
    } catch (error_) {
      const error = error_ as Error;
      this.logger.error(
        `Redis operation failed: ${error.message}`,
        context,
        error,
      );

      // Attempt to force reconnect
      const newClient = await this.forceReconnectAsync(client, error);
      // Retry the operation with the new/same client
      try {
        const result = await operation(newClient);
        return { result, client: newClient };
      } catch (retryError) {
        this.logger.error(
          `Redis operation failed after reconnection`,
          context,
          retryError as Error,
        );
        throw retryError;
      }
    }
  }
}

import {
  createClient,
  RedisModules,
  RedisFunctions,
  RedisScripts,
} from "@redis/client";

import { asyncTryCatch } from "../../../../common/utils/async-try-catch";
import { withTimeout } from "../../../../common/utils/with-timeout";

import { JobsLoggerService } from "../../../logger";
import { ApiLogContext } from "../../../logger/apis/dtos/api-log-context.dto";
import { IRedisConfig } from "../interfaces/index-redis-config";
import { RedisClientInstance } from "../types/redis-types";
import { RedisConnectionService } from "./abstract-redis-connection";

interface FullRedisConfig extends IRedisConfig {
  localRedisPassword: string;
  username: string;
  useTls: boolean;
}

export class BasicAuthRedisConnection extends RedisConnectionService {
  private isReconnectInProgress = false;

  public constructor(
    redisUrl: string,
    private readonly redisConfigService: FullRedisConfig,
    protected readonly customLogger: JobsLoggerService,
    usePool?: boolean,
    poolMin?: number,
    poolMax?: number,
  ) {
    super(redisUrl, usePool, poolMin, poolMax);
  }

  public async createClient(): Promise<RedisClientInstance> {
    const context: ApiLogContext = {
      method: "BasicAuthRedisConnection.createClient",
      service: "BasicAuthRedisConnection",
      caller: "",
      plant: 0,
    };

    const {
      localRedisPassword: password,
      username,
      useTls,
    } = this.redisConfigService;

    this.redisClientOptions = {
      password,
      pingInterval: 100_000,
      socket: useTls ? { tls: true } : { keepAlive: false },
      url: this.redisUrl,
      username,
    };

    const client = createClient<RedisModules, RedisFunctions, RedisScripts>(
      this.redisClientOptions,
    );
    this.customLogger.log("Client created...", context);

    client.on("error", async (error) => {
      this.customLogger.error("Redis Client Error:", context, error);
      await this.handleReconnect(client);
    });

    client.on("end", async () => {
      this.customLogger.log(
        "Redis connection closed, attempting reconnect...",
        context,
      );
      await this.handleReconnect(client);
    });

    await withTimeout(client.connect(), 10_000);
    this.customLogger.log("Redis connection Is Open", context);
    return client;
  }

  private async handleReconnect(client?: RedisClientInstance): Promise<void> {
    if (this.isReconnectInProgress) return;
    this.isReconnectInProgress = true;

    const context: ApiLogContext = {
      method: "BasicAuthRedisConnection.handleReconnect",
      service: "BasicAuthRedisConnection",
      caller: "",
      plant: 0,
    };

    try {
      if (client) {
        await asyncTryCatch({
          tryFn: async () => {
            client.destroy();
          },
          catchFn: () =>
            this.customLogger.warn(
              "Error during Redis client disconnect in reconnect",
              context,
            ),
        });
        client.removeAllListeners();
      }

      if (!this.usePool) this.redisClient = undefined;

      this.customLogger.log("Reconnecting to Redis...", context);

      if (!this.usePool) {
        const newClient = await this.createClient();
        this.redisClient = newClient;
      }

      this.customLogger.log("Reconnected to Redis successfully", context);
    } catch {
      this.customLogger.error("Failed to reconnect to Redis", context);
    } finally {
      this.isReconnectInProgress = false;
    }
  }
}

import { JobsLoggerService } from "../../../logger/jobs/services/jobs-logger.service";
import { RedisConnectionService } from "../connections/abstract-redis-connection";
import { AzureManagedRedisConnection } from "../connections/azure-managed-redis-redis-connection";
import { BasicAuthRedisConnection } from "../connections/basic-auth-redis-connection";
import { FullRedisConfig } from "../interfaces/index-redis-config";

/**
 * Factory function to create a Redis connection service.
 * @param redisConfigService Configuration for Redis.
 * @param logger Logger service for jobs.
 * @param usePool Optional flag to enable Redis connection pooling.
 * @returns Connected RedisConnectionService instance.
 */
export async function redisConnectionFactory(
  redisConfigService: FullRedisConfig,
  logger: JobsLoggerService,
  usePool?: boolean,
): Promise<RedisConnectionService> {
  const enablePool = usePool ?? false;
  let poolMin: number | undefined;
  let poolMax: number | undefined;
  if (enablePool) {
    // Only read from config if pooling is enabled
    poolMin = redisConfigService.redisPoolMinConnections ?? 2;
    poolMax = redisConfigService.redisPoolMaxConnections ?? 4;
  }

  const redisUrl = redisConfigService.useRedisLocal
    ? `redis://${redisConfigService.redisHostManagedRedis}`
    : `rediss://${redisConfigService.redisHostManagedRedis}`;

  const connection: RedisConnectionService = redisConfigService.useRedisLocal
    ? new BasicAuthRedisConnection(
        redisUrl,
        redisConfigService,
        logger,
        enablePool,
        poolMin,
        poolMax,
      )
    : new AzureManagedRedisConnection(
        redisUrl,
        logger,
        enablePool,
        poolMin,
        poolMax,
      );
  if (redisConfigService.isAJob !== "true") {
    await connection.connect();
  }

  return connection;
}

