import {
  RedisClientType,
  RedisClientOptions,
  RedisModules,
  RedisFunctions,
  RedisScripts,
} from "@redis/client";

// Explicitly add version '2' as the last generic parameter for RedisClientType
export type RedisClientInstance = RedisClientType<
  RedisModules,
  RedisFunctions,
  RedisScripts
>;

// Explicitly add version '2' as the last generic parameter for RedisClientOptions
export type CompatibleRedisClientOptions = RedisClientOptions<
  RedisModules,
  RedisFunctions,
  RedisScripts,
  2
>;

export type RedisClientMulti = ReturnType<RedisClientInstance["multi"]>;

export const ERROR_CODES = {
  default: { code: "default", defaultMessage: "Default error occurred" },
  failedShiftTrackingDtlEvents: {
    code: "failedShiftTrackingDtlEvents",
    defaultMessage: "Ingestion failed for shift_tracking_dtl events",
  },
  failedShiftTrackingStatusEvents: {
    code: "failedShiftTrackingStatusEvents",
    defaultMessage: "Ingestion failed for shift_tracking_status events",
  },
  incompleteApiManager: {
    code: "incompleteApiManager",
    defaultMessage: "API Manager setup is incomplete",
  },
  missingAlertConfig: {
    code: "missingAlertConfig",
    defaultMessage: "Alert Config Not Found",
  },
  unexpectedError: {
    code: "unexpectedError",
    defaultMessage: "An unexpected error occurred",
  },
} as const;

export type ErrorCode = keyof typeof ERROR_CODES;

export enum FUNCTIONAL_ERROR_STATUS {
  ACKNOWLEDGED = "ACKNOWLEDGED",
  AUTO_RESOLVED = "AUTO_RESOLVED",
  CREATED = "CREATED",
  ESCALATED = "ESCALATED",
  IGNORED = "IGNORED",
  PENDING_REPROCESS = "PENDING_REPROCESS",
  REPEATED = "REPEATED",
  REPROCESS_FAILED = "REPROCESS_FAILED",
  REPROCESSED = "REPROCESSED",
  RESOLVED = "RESOLVED",
}

import { ErrorCode, FUNCTIONAL_ERROR_STATUS } from "../constants";

/**
 * Represents a functional error log.
 */
export interface FunctionalLogDto {
  /**
   * Additional context useful for debugging or reprocessing.
   * Each integrating application can define its own structure.
   * In case of aggregaterdErrors, this field holds the context of initial instance which CREATED the error, later updates will not modify this property
   */
  context?: object;

  /** UTC timestamp when the error was first logged. */
  createdAt?: string;

  /** Human-readable English message describing the error. */
  defaultMessage?: string;

  /** Specific code identifying the error. Common-lib ERROR_CODE constants should be extended in case new error code is needed. */
  errorCode: ErrorCode;

  /** Name of the application that logged the error. */
  applicationName: string;

  /** Number of times this error occurred today for the same objectId. */
  numberOfOccurences?: number;

  /** Business key identifying the object causing the error (order, WorkCenter, PLC, etc). */
  objectId: string;

  /** Site or location where the error originated. */
  plant: number;

  /**
   * Identifier of the container app replica that logged the error.
   * Useful when scaling is enabled; also recorded for single-replica cases.
   */
  replicaId?: string;

  /** Current status of the error (e.g., CREATED, REPROCESSED, ACKNOWLEDGED). */
  status?: FUNCTIONAL_ERROR_STATUS;

  /**
   * ID linking this error to a specific HTTP request or execution trace.
   * Helps in debugging across multiple layers.
   */
  traceId?: string;

  /** UTC timestamp of the last update to this error record. */
  updatedAt?: string;

  /** User responsible for triggering the error, mainly relevant for UI-driven actions. */
  user?: string;
}

export interface FunctionalLogOptionsDto {
  /**
   * Best-effort logging.
   * Logs may be lost if the process exits (such as when there is no more process under execution due to app failure/restart or container being closed)
   * NEVER use for functional-critical paths when there is a chance the log will be lost since the call stack will be discarded by javascript
   * Can be used for long running apps when we know that event loop is always running
   */
  usefireAndForget?: boolean;

  /** Flag which controls whether the errors should be aggregated (combined) or not per day */
  aggregateErrorsByDay?: boolean;
}

