import { randomUUID } from "node:crypto";
import { Container, CosmosClient, Database } from "@azure/cosmos";
import { DefaultAzureCredential } from "@azure/identity";
import { Injectable, OnModuleInit } from "@nestjs/common";
import { DateTime } from "luxon";
import { ERROR_CODES, FUNCTIONAL_ERROR_STATUS } from "../constants";
import { FunctionalLogDto } from "../dtos/functional-log.dto";
import { FunctionalLogOptionsDto } from "../dtos/options-log.dto";
import { ICosmosSinkConfig, ILogSink } from "./sink.interface";

@Injectable()
export class CosmosSink implements ILogSink, OnModuleInit {
  private static isNotFoundError(error: unknown): boolean {
    return (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: number }).code === 404
    );
  }

  private static isConflictError(error: unknown): boolean {
    return (
      typeof error === "object" &&
      error !== null &&
      "code" in error &&
      (error as { code?: number }).code === 409
    );
  }

  public name = "cosmos";

  private readonly cosmosClient: CosmosClient;

  private readonly cosmosDatabase: Database;

  private readonly cosmosContainer: Container;

  public constructor(private readonly config: ICosmosSinkConfig) {
    if (!config.cosmosEndpoint && !config.cosmosClient) {
      throw new Error(
        "[CosmosSink] Either 'cosmosEndpoint' or 'cosmosClient' must be provided",
      );
    }

    this.config.replicaId = config.replicaId ?? randomUUID();
    this.config.aggregateErrorsByDay = config.aggregateErrorsByDay ?? true;

    this.cosmosClient =
      config.cosmosClient ??
      new CosmosClient({
        aadCredentials: new DefaultAzureCredential(),
        endpoint: config.cosmosEndpoint ?? "",
      });

    this.cosmosDatabase = this.cosmosClient.database(
      config.cosmosDatabaseName ?? "Mes",
    );
    this.cosmosContainer = this.cosmosDatabase.container(
      config.cosmosContainerName ?? "FunctionalLogs",
    );
  }

  public async onModuleInit(): Promise<void> {
    await this.validateConnection();
  }

  private async validateConnection(): Promise<void> {
    try {
      await this.cosmosDatabase.read(); // <-- checks DB existence
      await this.cosmosContainer.read(); // <-- checks container existence
    } catch (error_) {
      const error = `[StoredLoggerService][CosmosSink]CosmosDb connection could not be established: ${error_}`;
      throw new Error(error);
    }
  }

  public async write(
    type: "technical" | "functional",
    payload: FunctionalLogDto,
    options?: FunctionalLogOptionsDto,
  ): Promise<void> {
    const executeWrite = async (): Promise<void> => {
      try {
        // Use the options value if provided, otherwise fallback to class default which is instantiated from .env
        const aggregateErrors =
          options?.aggregateErrorsByDay ?? this.config.aggregateErrorsByDay;

        const now = DateTime.utc();
        const todayString = now.toISODate();
        const documentId = `${payload.plant}|${payload.applicationName}|${payload.errorCode}|${payload.objectId}|${aggregateErrors ? todayString : now.toISO()}`;

        if (aggregateErrors) {
          try {
            await this.cosmosContainer.item(documentId, payload.plant).patch([
              { op: "incr", path: "/numberOfOccurences", value: 1 },
              { op: "set", path: "/updatedAt", value: now.toISO() },
              {
                op: "set",
                path: "/status",
                value: FUNCTIONAL_ERROR_STATUS.REPEATED,
              },
            ]);

            return; // Done
          } catch (error: unknown) {
            if (!CosmosSink.isNotFoundError(error)) {
              throw error; // Unexpected error
            }
            // Document does not exist → will attempt CREATE
          }
        }

        try {
          await this.cosmosContainer.items.create({
            id: documentId,
            ...payload,
            createdAt: now.toISO(),
            defaultMessage:
              ERROR_CODES[payload.errorCode]?.defaultMessage ??
              ERROR_CODES.default.defaultMessage,
            numberOfOccurences: 1,
            replicaId: this.config.replicaId,
            status: FUNCTIONAL_ERROR_STATUS.CREATED,
            updatedAt: now.toISO(),
          });
          return;
        } catch (error: unknown) {
          if (!CosmosSink.isConflictError(error)) {
            throw error; // Unexpected error
          }
          // 409 → another concurrent request created the doc first, we now PATCH
        }
        await this.cosmosContainer.item(documentId, payload.plant).patch([
          { op: "incr", path: "/numberOfOccurences", value: 1 },
          { op: "set", path: "/updatedAt", value: now.toISO() },
          {
            op: "set",
            path: "/status",
            value: FUNCTIONAL_ERROR_STATUS.REPEATED,
          },
        ]);
      } catch (error) {
        console.error(
          `[StoredLoggerService][CosmosSink] Failed to write ${type} log for payload:`,
          payload,
          error,
        );
      }
    };
    // Fire-and-forget vs awaited execution
    if (options?.usefireAndForget) {
      setImmediate(() => {
        executeWrite();
      });
      return; // Resolve immediately
    }

    // Normal awaited execution
    await executeWrite();
  }
}

