@Injectable()
export class StoredLoggerService {
  private sinks: Array<ILogSink> = [];

  public constructor(private readonly cosmosSink: CosmosSink) {
    // Register default sinks
    this.addSink(this.cosmosSink);
  }

  public async functionalLog(
    payload: FunctionalLogDto,
    options?: FunctionalLogOptionsDto,
  ): Promise<void> {
    await Promise.allSettled(
      this.sinks.map((sink) => sink.write("functional", payload, options)),
    );
  }

  /**
   * For future extensibility
   * @param sink The sink to be added
   */
  public addSink(sink: ILogSink): void {
    this.sinks.push(sink);
  }

  public removeSink(name: string): void {
    this.sinks = this.sinks.filter((s) => s.name !== name);
  }
}

