  TelemetryConfigLoader,
} from "../interfaces/telemetry-config.interface";
import { AzureSdkFilterSpanProcessor } from "../processors/azure-sdk-filter-span-processor";

/** Internal state to prevent double initialization */
let telemetryInitialized = false;
let initializedServiceName: string | undefined;

/**
 * Default URL patterns to ignore for incoming requests.
 */
const DEFAULT_IGNORE_INCOMING_URLS = [
  "/probes",
  "/dapr/subscribe",
  "/metadata/identity/oauth2/token",
];

/**
 * Check if telemetry has been initialized.
 * @returns True if telemetry has been initialized, false otherwise.
 */
export function isTelemetryInitialized(): boolean {
  return telemetryInitialized;
}

/**
 * Get the service name that telemetry was initialized with.
 * @returns The service name if telemetry was initialized, undefined otherwise.
 */
export function getInitializedServiceName(): string | undefined {
  return initializedServiceName;
}

/**
 * Build HTTP instrumentation configuration.
 * @param config - The telemetry configuration containing URL patterns to ignore
 * @returns The HTTP instrumentation configuration object
 */
function buildHttpInstrumentationConfig(
  config: TelemetryConfig,
): HttpInstrumentationConfig {
  const ignoreIncoming =
    config.ignoreIncomingUrls ?? DEFAULT_IGNORE_INCOMING_URLS;
  const ignoreOutgoing = config.ignoreOutgoingUrls ?? [];

  return {
    enabled: true,
    ignoreIncomingRequestHook: (request: IncomingMessage): boolean => {
      // Always ignore OPTIONS (CORS preflight)
      if (request.method === "OPTIONS") return true;

      // Ignore root path
      if (request.url === "/") return true;

      // Check configured patterns
      const url = request.url ?? "";
      return ignoreIncoming.some((pattern) => url.includes(pattern));
    },
    ignoreOutgoingRequestHook: (options: RequestOptions): boolean => {
      const path = options.path ?? "";
      return ignoreOutgoing.some((pattern) => path.includes(pattern));
    },
  };
}

/**
 * Build span processors array.
 * @param config - The telemetry configuration containing custom span processors
 * @returns An array of span processors including the Azure SDK filter and any custom processors
 */
function buildSpanProcessors(config: TelemetryConfig): Array<SpanProcessor> {
  const processors: Array<SpanProcessor> = [new AzureSdkFilterSpanProcessor()];

  if (config.customSpanProcessors?.length) {
    processors.push(...config.customSpanProcessors);
  }

  return processors;
}

/**
 * Initialize Azure Monitor OpenTelemetry.
 *
 * This function MUST be called at the very start of your application,
 * BEFORE importing any framework (NestJS, Express, etc.) or instrumented libraries.
 * @example
 * ```typescript
 * // At the top of your main entry point (e.g., main.ts)
 * import { initializeTelemetry } from '@mesx/common-lib';
 *
 * initializeTelemetry({
 *   enableTelemetry: true,
 *   connectionString: process.env.APPLICATIONINSIGHTS_CONNECTION_STRING!,
 *   serviceName: 'my-service',
 *   samplingRatio: 0.5,
 * });
 *
 * // Now import your framework
 * import { NestFactory } from '@nestjs/core';
 * ```
 * @param config - Telemetry configuration provided by the consumer app
 * @returns Result indicating success or failure
 */
export function initializeTelemetry(
  config: TelemetryConfig,
): TelemetryInitResult {
  // Prevent double initialization
  if (telemetryInitialized) {
    console.warn(
      `[Telemetry] Already initialized for service: ${initializedServiceName}. Skipping.`,
    );
    return {
      success: true,
      serviceName: initializedServiceName,
    };
  }

  // Check if telemetry is disabled
  if (!config.enableTelemetry) {
    console.warn(
      "[Telemetry] Disabled via configuration. Skipping initialization.",
    );
    return {
      success: true,
      error: "Telemetry disabled",
    };
  }

  // Validate connection string
  if (!config.connectionString) {
    const error = "Connection string is required when telemetry is enabled";
    console.error(`[Telemetry] ${error}`);
    return {
      success: false,
      error,
    };
  }

  // Validate service name
  if (!config.serviceName) {
    const error = "Service name is required";
    console.error(`[Telemetry] ${error}`);
    return {
      success: false,
      error,
    };
  }

  try {
    const hostName = config.hostName ?? os.hostname();
    const HOST_NAME_ATTRIBUTE = "host.name";
    const options: AzureMonitorOpenTelemetryOptions = {
      azureMonitorExporterOptions: {
        connectionString: config.connectionString,
      },
      instrumentationOptions: {
        http: buildHttpInstrumentationConfig(config),
        azureSdk: { enabled: config.enableAzureSdkInstrumentation ?? true },
        redis: { enabled: config.enableRedisInstrumentation ?? true },
        redis4: { enabled: config.enableRedisInstrumentation ?? true },
      },
      resource: resourceFromAttributes({
        [ATTR_SERVICE_NAME]: config.serviceName,
        [HOST_NAME_ATTRIBUTE]: hostName,
      }),
      samplingRatio: config.samplingRatio ?? 1,
      spanProcessors: buildSpanProcessors(config),
    };

    useAzureMonitor(options);

    telemetryInitialized = true;
    initializedServiceName = config.serviceName;

    return {
      success: true,
      serviceName: config.serviceName,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[Telemetry] Failed to initialize: ${message}`);
    return {
      success: false,
      error: message,
    };
  }
}

/**
 * Bootstrap telemetry with an async configuration loader.
 *
 * Use this when your configuration needs to be loaded asynchronously
 * (e.g., from Azure App Configuration, Key Vault, or remote config).
 * @example
 * ```typescript
 * // At the top of your main entry point
 * import { bootstrapTelemetry } from '@mesx/common-lib';
 *
 * await bootstrapTelemetry(async () => ({
 *   enableTelemetry: true,
 *   connectionString: await getFromKeyVault('app-insights-connection-string'),
 *   serviceName: 'my-service',
 *   samplingRatio: 0.5,
 * }));
 *
 * // Now import your framework
 * const { NestFactory } = await import('@nestjs/core');
 * ```
 * @param loader - Async function that returns the telemetry configuration
 * @returns Promise resolving to the initialization result
 */
export async function bootstrapTelemetry(
  loader: TelemetryConfigLoader,
): Promise<TelemetryInitResult> {
  try {
    const config = await loader();
    return initializeTelemetry(config);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[Telemetry] Failed to load configuration: ${message}`);
    return {
      success: false,
      error: `Config loader failed: ${message}`,
    };
  }
}

/**
 * Reset telemetry state (for testing purposes only).
 * @internal
 */
export function resetTelemetryStateForTesting(): void {
  telemetryInitialized = false;
  initializedServiceName = undefined;
}

