import { SpanProcessor, ReadableSpan } from "@opentelemetry/sdk-trace-base";
import { AzureSdkFilterConfig } from "../interfaces/telemetry-config.interface";

export type { SpanProcessor } from "@opentelemetry/sdk-trace-base";

/**
 * Custom Span Processor that filters out Azure SDK internal operations
 */
export class AzureSdkFilterSpanProcessor implements SpanProcessor {
  private readonly ignorePatterns: Array<string>;

  private filteringEnabled = true;

  public constructor(config?: AzureSdkFilterConfig) {
    this.ignorePatterns = config?.ignorePatterns ?? [
      "credential",
      "managedidentitycredential",
      "containerclient-",
      "microsoft.aad",
      "microsoft.storage",
      "microsoft.appconfiguration",
      "inproc",
    ];
  }

  private shouldIgnoreSpan(span: ReadableSpan): boolean {
    const spanName = (span.name || "").toLowerCase();
    const attributes = span.attributes || {};
    const azNamespace = String(attributes["az.namespace"] || "").toLowerCase();
    const operation = String(attributes["operation"] || "").toLowerCase();
    const httpUrl = String(attributes["http.url"] || "").toLowerCase();
    const peerService = String(attributes["peer.service"] || "").toLowerCase();
    const component = String(attributes["component"] || "").toLowerCase();

    const searchText = `${spanName} ${azNamespace} ${operation} ${httpUrl} ${peerService} ${component}`;

    return this.ignorePatterns.some((pattern) => searchText.includes(pattern));
  }

  public onStart(): void {
    this.filteringEnabled = Boolean(this.filteringEnabled);
  }

  public onEnd(span: ReadableSpan): void {
    if (this.shouldIgnoreSpan(span)) {
      this.filteringEnabled = Boolean(this.filteringEnabled);
    }
  }

  public async shutdown(): Promise<void> {
    this.filteringEnabled = false;
  }

  public async forceFlush(): Promise<void> {
    this.filteringEnabled = Boolean(this.filteringEnabled);
  }
}

