}

/**
 * Builds the HTTP instrumentation configuration for OpenTelemetry.
 * Configures which incoming and outgoing HTTP requests should be ignored
 * based on default or user-provided patterns.
 * @param config - The telemetry configuration object.
 * @returns The HTTP instrumentation configuration to use with OpenTelemetry.
 */
function buildHttpInstrumentation(
  config: TelemetryConfig,
): HttpInstrumentationConfig {
  const ignoreIncoming =
    config.ignoreIncomingUrls ?? DEFAULT_IGNORE_INCOMING_URLS;
  const ignoreOutgoing = config.ignoreOutgoingUrls ?? [];

  return {
    ignoreIncomingRequestHook: (request: IncomingMessage): boolean => {
      if (request.method === "OPTIONS") return true;
      if (request.url === "/") return true;
      const url = request.url ?? "";
      return ignoreIncoming.some((pattern) => url.includes(pattern));
    },

    // Hook to ignore certain outgoing requests
    ignoreOutgoingRequestHook: (options: RequestOptions): boolean => {
      const path = options.path ?? "";
      return ignoreOutgoing.some((pattern) => path.includes(pattern));
    },
  };
}

/**
 * Builds the array of OpenTelemetry span processors to be used during tracing.
 *
 * Always includes the default `AzureSdkFilterSpanProcessor`, and optionally
 * appends any custom span processors provided in the telemetry configuration.
 * @param config - The telemetry configuration object.
 * @returns An array of `SpanProcessor` instances for the trace pipeline.
 */
function buildSpanProcessors(config: TelemetryConfig): Array<SpanProcessor> {
  const processors: Array<SpanProcessor> = [new AzureSdkFilterSpanProcessor()];

  if (config.customSpanProcessors?.length) {
    processors.push(...config.customSpanProcessors);
  }

  return processors;
}

/**
 * Initializes telemetry for the application using the provided configuration.
 * Sets up tracing, metrics, and HTTP instrumentation based on the
 * `TelemetryConfig`. Prevents double initialization by returning
 * early if telemetry has already been initialized.
 * @param config - The telemetry configuration provided by the consumer application.
 * @returns An object indicating whether initialization succeeded,
 *          including the configured service name if applicable.
 */
export function initializeTelemetry(
  config: TelemetryConfig,
): TelemetryInitResult {
  // Prevent double initialization
  if (telemetryInitialized) {
    return {
      success: true,
      serviceName: initializedServiceName,
    };
  }

  // Check if telemetry is disabled
  if (!config.enableTelemetry) {
    return {
      success: true,
      error: "Telemetry disabled",
    };
  }

  // Validate connection string
  if (!config.connectionString) {
    const error = "Connection string is required when telemetry is enabled";
    console.error(`[Telemetry] ${error}`);
    return {
      success: false,
      error,
    };
  }

  // Validate service name
  if (!config.serviceName) {
    const error = "Service name is required";
    console.error(`[Telemetry] ${error}`);
    return {
      success: false,
      error,
    };
  }
  try {
    // Suppress Azure SDK internal diagnostic logs (e.g., _APPRESOURCEPREVIEW_)
    setLogLevel("error");

    const hostName = config.hostName ?? os.hostname();
    const HOST_NAME_ATTRIBUTE = "host.name";
    const options: AzureMonitorOpenTelemetryOptions = {
      azureMonitorExporterOptions: {
        connectionString: config.connectionString,
      },
      enableLiveMetrics: config.enableLiveMetrics ?? false,
      enablePerformanceCounters: config.enablePerformanceCounters ?? false,
      enableStandardMetrics: config.enableMetrics ?? false,
      enableTraceBasedSamplingForLogs:
        config.enableTraceBasedSamplingForLogs ?? false,
      instrumentationOptions: {
        http: buildHttpInstrumentation(config),
        azureSdk: { enabled: config.enableAzureSdkInstrumentation ?? false },
        redis: { enabled: config.enableRedisInstrumentation ?? false },
        redis4: { enabled: config.enableRedisInstrumentation ?? false },
      },
      resource: resourceFromAttributes({
        [ATTR_SERVICE_NAME]: config.serviceName,
        [HOST_NAME_ATTRIBUTE]: hostName,
      }),
      samplingRatio: config.samplingRatio ?? 0,
      spanProcessors: buildSpanProcessors(config),
    };

    useAzureMonitor(options);

    telemetryInitialized = true;
    initializedServiceName = config.serviceName;

    return {
      success: true,
      serviceName: config.serviceName,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      error: message,
    };
  }
}

/**
 *
 * @param loader - Async function that returns the telemetry configuration
 * @returns Promise resolving to the initialization result
 */
export async function bootstrapTelemetry(
  loader: TelemetryConfigLoader,
): Promise<TelemetryInitResult> {
  try {
    const config = await loader();
    return initializeTelemetry(config);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[Telemetry] Failed to load configuration: ${message}`);
    return {
      success: false,
      error: `Config loader failed: ${message}`,
    };
  }
}

/**
 * Reset telemetry state (for testing purposes only).
 * @internal
 */
export function resetTelemetryState(): void {
  telemetryInitialized = false;
  initializedServiceName = undefined;
}

