/**
 * Singleton telemetry metrics service implementation.
 * Framework-agnostic - can be used with any framework or without one.
 */
class TelemetryMetricsServiceImpl {
  private containerHost = "";

  private meter: Meter | undefined = undefined;

  private serviceName = "";

  private initialized = false;

  // Cached metric instruments for performance
  private readonly counters: Map<string, Counter> = new Map();

  private readonly histograms: Map<string, Histogram> = new Map();

  /**
   * Initializes the telemetry metrics service.
   *
   * Must be called **after** `initializeTelemetry()` and **before** tracking any metrics.
   * Sets up the meter instance and the service/host information.
   * @param config - Configuration for the metrics service, including service name
   *                 and optional hostname override.
   */
  public initialize(config: TelemetryMetricsConfig): void {
    if (this.initialized) {
      return;
    }

    this.serviceName = config.serviceName;
    this.containerHost = config.hostName ?? os.hostname();
    this.meter = metrics.getMeter(`${config.serviceName}-metrics`);
    this.initialized = true;
  }

  /**
   * Checks whether the telemetry metrics service has been initialized.
   * @returns `true` if the service has been initialized and is ready for
   *          tracking metrics; otherwise, `false`.
   */
  public isInitialized(): boolean {
    return this.initialized;
  }

  /**
   * Returns the name of the telemetry metrics service.
   * @returns The configured service name.
   */
  public getServiceName(): string {
    return this.serviceName;
  }

  /**
   * Builds a dimensions object for metrics, always including the container host.
   *
   * Merges optional metric dimensions provided by the caller with the
   * `containerHost` property of this service.
   * @param dimensions - Optional metric dimensions to include (e.g., `plantCode`, `status`, `topic`, `partitionId`).
   * @returns A record of dimension keys and values suitable for metrics reporting.
   */
  private buildDimensions(
    dimensions: MetricDimensions,
  ): Record<string, string> {
    const result: Record<string, string> = {
      containerHost: this.containerHost,
    };

    if (dimensions.plantCode) result.plantCode = dimensions.plantCode;
    if (dimensions.status) result.status = dimensions.status;
    if (dimensions.topic) result.topic = dimensions.topic;
    if (dimensions.partitionId) result.partitionId = dimensions.partitionId;

    return result;
  }

  /**
   * Retrieves an existing counter by name, or creates a new one if it does not exist.
   * @param name - The name of the counter to retrieve or create.
   * @returns The `Counter` instance associated with the given name,
   *          or `undefined` if the meter has not been initialized.
   */
  private getCounter(name: string): Counter | undefined {
    if (!this.meter) return undefined;

    let counter = this.counters.get(name);
    if (!counter) {
      counter = this.meter.createCounter(name, {
        description: `Counter for ${name}`,
      });
      this.counters.set(name, counter);
    }
    return counter;
  }

  /**
   * Retrieves an existing histogram by name, or creates a new one if it does not exist.
   * @param name - The name of the histogram to retrieve or create.
   * @param unit - The unit of measurement for the histogram (default: `"ms"`).
   * @returns The `Histogram` instance associated with the given name,
   *          or `undefined` if the meter has not been initialized.
   */
  private getHistogram(name: string, unit = "ms"): Histogram | undefined {
    if (!this.meter) return undefined;

    let histogram = this.histograms.get(name);
    if (!histogram) {
      histogram = this.meter.createHistogram(name, {
        description: `Histogram for ${name}`,
        unit,
      });
      this.histograms.set(name, histogram);
    }
    return histogram;
  }

  /**
   * Tracks a counter metric by adding a specified value.
   *
   * Requires the metrics service to be initialized via `initialize()`.
   * The metric is created if it does not already exist.
   * @param name - The name of the counter metric.
   * @param value - The value to add to the counter.
   * @param dimensions - Optional key-value dimensions to associate with the metric.
   */
  public trackCounter(
    name: string,
    value: number,
    dimensions: MetricDimensions = {},
  ): void {
    if (!this.initialized) {
      return;
    }

    try {
      const counter = this.getCounter(name);
      if (counter) {
        counter.add(value, this.buildDimensions(dimensions));
      }
    } catch (error) {
      console.warn(
        `[TelemetryMetrics] Failed to track counter ${name}:`,
        (error as Error).message,
      );
    }
  }

  /**
   * Tracks a histogram metric by recording a specified value.
   *
   * Requires the metrics service to be initialized via `initialize()`.
   * The histogram is created if it does not already exist.
   * @param name - The name of the histogram metric.
   * @param value - The value to record in the histogram.
   * @param dimensions - Optional key-value dimensions to associate with the metric.
   * @param unit - The unit of measurement for the histogram (default: `"ms"`).
   */
  public trackHistogram(
    name: string,
    value: number,
    dimensions: MetricDimensions = {},
    unit = "ms",
  ): void {
    if (!this.initialized) {
      return;
    }

    try {
      const histogram = this.getHistogram(name, unit);
      if (histogram) {
        histogram.record(value, this.buildDimensions(dimensions));
      }
    } catch (error) {
      console.warn(
        `[TelemetryMetrics] Failed to track histogram ${name}:`,
        (error as Error).message,
      );
    }
  }

  /**
   * Tracks the processing of an event by incrementing the `event_processed_count` counter.
   *
   * Associates optional dimensions such as status, plant code, topic, and partition ID.
   * @param status - The processing status of the event (e.g., success, failure).
   * @param plantCode - Optional plant code associated with the event.
   * @param topic - Optional topic name for the event.
   * @param partitionId - Optional partition ID for the event.
   */
  public trackEventProcessed(
    status: PROCESSING_STATUS,
    plantCode?: string,
    topic?: string,
    partitionId?: string,
  ): void {
    this.trackCounter("event_processed_count", 1, {
      status,
      plantCode,
      topic,
      partitionId,
    });
  }

  /**
   * Tracks the duration of event processing by recording it in the
   * `event_processing_duration_ms` histogram.
   *
   * Associates optional dimensions such as status, plant code, topic, and partition ID.
   * @param durationMs - The duration of the event processing in milliseconds.
   * @param status - The processing status of the event (e.g., success, failure).
   * @param plantCode - Optional plant code associated with the event.
   * @param topic - Optional topic name for the event.
   * @param partitionId - Optional partition ID for the event.
   */
  public trackEventProcessingDuration(
    durationMs: number,
    status: PROCESSING_STATUS,
    plantCode?: string,
    topic?: string,
    partitionId?: string,
  ): void {
    this.trackHistogram("event_processing_duration_ms", durationMs, {
      status,
      plantCode,
      topic,
      partitionId,
    });
  }

  /**
   * Resets the telemetry metrics service state.
   *
   * This method clears all internal state, including counters, histograms,
   * meter instance, and service information. Intended **for testing purposes only**.
   * @internal
   */
  public reset(): void {
    this.initialized = false;
    this.serviceName = "";
    this.containerHost = "";
    this.meter = undefined;
    this.counters.clear();
    this.histograms.clear();
  }
}

/**
 * Singleton instance of TelemetryMetricsService.
 */
export const telemetryMetrics = new TelemetryMetricsServiceImpl();

